"""Monthly HTML report from stored costs and recommendations. Figures are not generated by the model."""

from html import escape

from sqlalchemy.orm import Session

from app.core.exceptions import FinOpsError
from app.core.money import as_decimal
from app.db.models import Report
from app.services.account_service import require_account
from app.services.cost_service import get_cost_summary
from app.services.recommendation_service import get_savings, list_recommendations


def generate_monthly_report(session: Session, narrative: str | None = None) -> dict:
    account = require_account(session)
    summary = get_cost_summary(session)
    savings = get_savings(session)
    recommendations = list_recommendations(session)["recommendations"][:8]
    month = summary["current_period_label"]
    html = _html(account.aws_account_id, summary, savings, recommendations, narrative)
    record = Report(
        account_id=account.id,
        report_month=month,
        total_cost=as_decimal(summary["current_monthly_cost"]),
        previous_month_cost=as_decimal(summary["previous_monthly_cost"]),
        potential_savings=as_decimal(savings["potential_monthly_savings"]),
        realized_savings=as_decimal(0),
        report_json={"html": html, "narrative": narrative, "currency": summary["currency"]},
    )
    session.add(record)
    session.commit()
    return _payload(record)


def latest_monthly_report(session: Session) -> dict:
    account = require_account(session)
    record = (
        session.query(Report)
        .filter(Report.account_id == account.id)
        .order_by(Report.id.desc())
        .first()
    )
    if record is None:
        raise FinOpsError("No monthly report has been generated yet.", status_code=404)
    return _payload(record)


def _payload(record: Report) -> dict:
    body = record.report_json or {}
    return {
        "id": record.id,
        "report_month": record.report_month,
        "currency": body.get("currency") or "USD",
        "total_cost": float(record.total_cost),
        "previous_month_cost": float(record.previous_month_cost),
        "potential_savings": float(record.potential_savings),
        "realized_savings": float(record.realized_savings),
        "html": body.get("html") or "",
        "narrative": body.get("narrative"),
    }


def _html(account_id: str, summary: dict, savings: dict, recommendations: list[dict], narrative: str | None) -> str:
    currency = escape(str(summary["currency"]))
    rows = []
    for item in recommendations:
        rows.append(
            "<li><strong>{title}</strong> — {current} current, {saving} estimated potential savings. {risk} risk.</li>".format(
                title=escape(item["title"]),
                current=escape(f"{item['current_monthly_cost']} {currency}"),
                saving=escape(f"{item['estimated_monthly_savings']} {currency}"),
                risk=escape(item["risk_level"]),
            )
        )
    narrative_block = ""
    if narrative:
        narrative_block = f"<h2>Advisor narrative</h2><p>{escape(narrative)}</p>"
    return f"""
<article>
  <h1>AWS Cost Guardian monthly report</h1>
  <p>Account {escape(account_id)}. {escape(summary['current_period_label'])}.</p>
  <p>Current {summary['current_monthly_cost']} {currency}. Previous {summary['previous_monthly_cost']} {currency}.</p>
  <p>{escape(savings['label'])}: {savings['potential_monthly_savings']} {currency} / month.</p>
  <p>{escape(summary.get('history_note') or '')}</p>
  <h2>Recommendations</h2>
  <ul>
    {''.join(rows) or '<li>No recommendations are stored.</li>'}
  </ul>
  {narrative_block}
  <p>PDF export is not generated yet.</p>
</article>
""".strip()
